package modelcheckauth

import (
	"context"
	"strings"
	"testing"
	"time"
)

func TestVerifySystemAccountCredentialsUsesNodePBKDF2SaltText(t *testing.T) {
	db := newModelCheckAuthPGDatabase(t)
	// Generated by crypto.pbkdf2Sync(password, saltText, 600000, 32,
	// 'sha512'), where saltText is not decoded before PBKDF2.
	const passwordHash = "pbkdf2$sha512$600000$MDEyMzQ1Njc4OWFiY2RlZg$o_blJJQW7MSuq66Eqr2dTpetR6YkjZQMwSeU2Dfd0p0"
	if _, err := db.Exec(`INSERT INTO juhe_business.system_accounts (id,username,display_name,role,status,password_hash,must_change_password,created_at,updated_at) VALUES ('acct','Admin','管理员','admin','active',$1,1,'','')`, passwordHash); err != nil {
		t.Fatal(err)
	}
	auth, err := New(db, Postgres, nil)
	if err != nil {
		t.Fatal(err)
	}
	verified, ok, err := auth.VerifySystemAccountCredentials(context.Background(), "admin", "correct horse battery staple")
	if err != nil || !ok {
		t.Fatalf("verified=%+v ok=%v err=%v", verified, ok, err)
	}
	if verified.SystemAccountID != "acct" || verified.Username != "Admin" || verified.Role != "admin" || !verified.MustChangePassword || verified.CredentialRevision != hashString(passwordHash) {
		t.Fatalf("verified=%+v", verified)
	}
	issued, loginVerified, ok, err := auth.Login(context.Background(), "ADMIN", "correct horse battery staple", 14)
	if err != nil || !ok || issued.Token == "" || loginVerified.CredentialRevision != verified.CredentialRevision {
		t.Fatalf("issued=%+v verified=%+v ok=%v err=%v", issued, loginVerified, ok, err)
	}
	var sessionCount int
	if err := db.QueryRow(`SELECT COUNT(*) FROM juhe_business.system_sessions WHERE system_account_id='acct'`).Scan(&sessionCount); err != nil || sessionCount != 1 {
		t.Fatalf("sessionCount=%d err=%v", sessionCount, err)
	}
	for _, input := range []struct{ username, password string }{{"admin", "wrong"}, {"missing", "correct horse battery staple"}, {"", "correct horse battery staple"}} {
		if _, ok, err := auth.VerifySystemAccountCredentials(context.Background(), input.username, input.password); err != nil || ok {
			t.Fatalf("input=%+v ok=%v err=%v", input, ok, err)
		}
	}
}

func TestLegacyPasswordFailurePadsToTargetCost(t *testing.T) {
	// SEC-07: a wrong password against a legacy 120000 hash must burn the
	// same PBKDF2 budget as a current 600000 hash or the missing/inactive
	// dummy arm, otherwise response latency reveals that the account exists.
	const legacyHash = "pbkdf2$sha512$120000$MDEyMzQ1Njc4OWFiY2RlZg$MB16ie0MUIkgM1Xio7iCM8x9uCDqJJf5rkQ297w84fg"
	const currentHash = "pbkdf2$sha512$600000$MDEyMzQ1Njc4OWFiY2RlZg$o_blJJQW7MSuq66Eqr2dTpetR6YkjZQMwSeU2Dfd0p0"

	before := legacyVerificationPadIterations.Load()
	if verifyNodePBKDF2Password("wrong", legacyHash) {
		t.Fatal("wrong password verified against legacy hash")
	}
	if got := legacyVerificationPadIterations.Load() - before; got != NodePasswordHashIterations-120000 {
		t.Fatalf("legacy failure pad = %d, want %d", got, NodePasswordHashIterations-120000)
	}

	before = legacyVerificationPadIterations.Load()
	if !verifyNodePBKDF2Password("correct horse battery staple", legacyHash) {
		t.Fatal("correct password rejected against legacy hash")
	}
	if got := legacyVerificationPadIterations.Load() - before; got != 0 {
		t.Fatalf("successful legacy verify padded %d iterations, want 0", got)
	}

	before = legacyVerificationPadIterations.Load()
	if verifyNodePBKDF2Password("wrong", currentHash) {
		t.Fatal("wrong password verified against current hash")
	}
	if got := legacyVerificationPadIterations.Load() - before; got != 0 {
		t.Fatalf("current-hash failure padded %d iterations, want 0", got)
	}
}

// TestVerifySystemAccountCredentialsUpgradesLegacyPBKDF2Iterations pins the
// T169 migration: a 120000-iteration hash still verifies and is re-hashed with
// NodePasswordHashIterations on the successful login, with the session fence
// derived from the upgraded hash. A wrong password never rewrites the row.
func TestVerifySystemAccountCredentialsUpgradesLegacyPBKDF2Iterations(t *testing.T) {
	db := newModelCheckAuthPGDatabase(t)
	const legacyHash = "pbkdf2$sha512$120000$MDEyMzQ1Njc4OWFiY2RlZg$MB16ie0MUIkgM1Xio7iCM8x9uCDqJJf5rkQ297w84fg"
	const password = "correct horse battery staple"
	if _, err := db.Exec(`INSERT INTO juhe_business.system_accounts (id,username,display_name,role,status,password_hash,must_change_password,created_at,updated_at) VALUES ('legacy','legacy','Legacy','admin','active',$1,0,'',''),('wrong','wrong','Wrong','admin','active',$1,0,'','')`, legacyHash); err != nil {
		t.Fatal(err)
	}
	now := time.Date(2026, 11, 6, 12, 0, 0, 0, time.UTC)
	auth, err := New(db, Postgres, func() time.Time { return now })
	if err != nil {
		t.Fatal(err)
	}
	ctx := context.Background()

	// A failed verification must not touch the stored legacy hash.
	if _, ok, err := auth.VerifySystemAccountCredentials(ctx, "wrong", "not-the-password"); err != nil || ok {
		t.Fatalf("wrong password ok=%v err=%v", ok, err)
	}
	var wrongHash string
	if err := db.QueryRow(`SELECT password_hash FROM juhe_business.system_accounts WHERE id='wrong'`).Scan(&wrongHash); err != nil || wrongHash != legacyHash {
		t.Fatalf("wrong-password hash=%q err=%v, want untouched legacy hash", wrongHash, err)
	}

	verified, ok, err := auth.VerifySystemAccountCredentials(ctx, "legacy", password)
	if err != nil || !ok {
		t.Fatalf("legacy verify = %+v ok=%v err=%v", verified, ok, err)
	}
	var upgradedHash, updatedAt string
	if err := db.QueryRow(`SELECT password_hash,updated_at FROM juhe_business.system_accounts WHERE id='legacy'`).Scan(&upgradedHash, &updatedAt); err != nil {
		t.Fatal(err)
	}
	if upgradedHash == legacyHash || !strings.HasPrefix(upgradedHash, "pbkdf2$sha512$600000$") {
		t.Fatalf("upgraded hash = %q", upgradedHash)
	}
	if verified.CredentialRevision != hashString(upgradedHash) {
		t.Fatalf("revision = %q, want hash of upgraded hash", verified.CredentialRevision)
	}
	if updatedAt != nodeISOTime(now) {
		t.Fatalf("upgraded updated_at = %q, want %q", updatedAt, nodeISOTime(now))
	}

	// The upgraded hash is already at the target, so a second check is a no-op.
	again, ok, err := auth.VerifySystemAccountCredentials(ctx, "legacy", password)
	if err != nil || !ok || again.CredentialRevision != verified.CredentialRevision {
		t.Fatalf("repeat verify = %+v ok=%v err=%v", again, ok, err)
	}
	var stableHash string
	if err := db.QueryRow(`SELECT password_hash FROM juhe_business.system_accounts WHERE id='legacy'`).Scan(&stableHash); err != nil || stableHash != upgradedHash {
		t.Fatalf("repeat verify rewrote hash = %q err=%v", stableHash, err)
	}

	// Login fences the session on the upgraded hash and still accepts the
	// original plaintext.
	issued, loginVerified, ok, err := auth.Login(ctx, "legacy", password, 7)
	if err != nil || !ok || issued.Token == "" || loginVerified.CredentialRevision != hashString(upgradedHash) {
		t.Fatalf("login issued=%+v verified=%+v ok=%v err=%v", issued, loginVerified, ok, err)
	}
}

func TestNewNodePasswordHashUsesTargetIterations(t *testing.T) {
	if NodePasswordHashIterations != 600000 {
		t.Fatalf("NodePasswordHashIterations = %d, want 600000", NodePasswordHashIterations)
	}
	passwordHash, err := HashNodePassword("t169-password")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.HasPrefix(passwordHash, "pbkdf2$sha512$600000$") {
		t.Fatalf("new hash = %q", passwordHash)
	}
	if iterations, ok := parseNodePasswordHashIterations(passwordHash); !ok || iterations != NodePasswordHashIterations {
		t.Fatalf("parsed iterations = %d ok=%v", iterations, ok)
	}
	if !verifyNodePBKDF2Password("t169-password", passwordHash) {
		t.Fatal("new hash must verify its password")
	}
	if verifyNodePBKDF2Password("other-password", passwordHash) {
		t.Fatal("new hash must reject a different password")
	}
}

func TestDummySystemAccountPasswordHashUsesTargetIterations(t *testing.T) {
	if !strings.HasPrefix(dummySystemAccountPasswordHash, "pbkdf2$sha512$600000$") {
		t.Fatalf("dummy hash = %q", dummySystemAccountPasswordHash)
	}
	iterations, ok := parseNodePasswordHashIterations(dummySystemAccountPasswordHash)
	if !ok || iterations != NodePasswordHashIterations {
		t.Fatalf("dummy iterations = %d ok=%v, want %d", iterations, ok, NodePasswordHashIterations)
	}
}

func TestVerifyNodePBKDF2PasswordRejectsInvalidIterations(t *testing.T) {
	// 32 zero bytes base64url-encoded without padding.
	const digest = "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
	for _, iterations := range []string{"0", "-1", "abc", "1e6", "99999999999999999999", ""} {
		passwordHash := "pbkdf2$sha512$" + iterations + "$salt$" + digest
		if verifyNodePBKDF2Password("pw", passwordHash) {
			t.Fatalf("iterations %q must be rejected", iterations)
		}
	}
	if !verifyNodePBKDF2Password("correct horse battery staple", "pbkdf2$sha512$120000$MDEyMzQ1Njc4OWFiY2RlZg$MB16ie0MUIkgM1Xio7iCM8x9uCDqJJf5rkQ297w84fg") {
		t.Fatal("legacy 120000 hash must still verify")
	}
}

func TestVerifySystemAccountCredentialsFailsClosedForMalformedOrDisabledHash(t *testing.T) {
	db := newModelCheckAuthPGDatabase(t)
	if _, err := db.Exec(`INSERT INTO juhe_business.system_accounts (id,username,display_name,role,status,password_hash,must_change_password,created_at,updated_at) VALUES ('bad','bad','Bad','admin','active','pbkdf2$sha512$0$salt$bad',0,'',''),('off','off','Off','admin','disabled','pbkdf2$sha512$120000$salt$MB16ie0MUIkgM1Xio7iCM8x9uCDqJJf5rkQ297w84fg',0,'','')`); err != nil {
		t.Fatal(err)
	}
	auth, _ := New(db, Postgres, nil)
	for _, username := range []string{"bad", "off"} {
		if _, ok, err := auth.VerifySystemAccountCredentials(context.Background(), username, "correct horse battery staple"); err != nil || ok {
			t.Fatalf("username=%s ok=%v err=%v", username, ok, err)
		}
	}
}
